function getRavellawTranslation(key, lang) {
    if (ravellawTranslations[lang] && ravellawTranslations[lang][key]) {
        return ravellawTranslations[lang][key];
    }
    if (ravellawTranslations.en && ravellawTranslations.en[key]) {
        return ravellawTranslations.en[key];
    }
    return null;
}

function applyRavellawTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.ravel-law.')) {
            const translation = getRavellawTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyRavellawTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyRavellawTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyRavellawTranslations(currentLang);
}


